import{_ as e,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-03-14 :: Ceph Performance meeting","description":"","frontmatter":{"title":"2019-03-14 :: Ceph Performance meeting","date":"2019-03-14T00:00:00.000Z","updated":"2019-04-15T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PR更新","库优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-03-14_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-03-14_-_-_Ceph_Performance_meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-03-14_-_-_Ceph_Performance_meeting.md"};function r(s,i,a,p,g,c){return l(),o("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年3月14日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储项目性能更新与讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、PR更新与讨论</strong></p><ol><li><p><strong>新PR</strong>：</p><ul><li>一项关于信使应用的PR报告了显著的增长，值得进一步研究。</li><li>一项针对异步连接的优化PR，专门优化回环连接。</li><li>一项针对MDS的PR，将不必要的标准列表使用转换为标准向量。</li><li>一项更新EM时钟的PR，可能包含性能提升。</li><li>一项改进对象映射性能的PR。</li><li>一项异步信使优化PR，等待知识更新。</li><li>一项信使PR，批量处理和发送消息，但性能测试未改善。</li><li>一项Rgw性能PR，包含修复和优化。</li><li>一项Lib RB多缓存回线程PR，与PR 6.6.7.5有所重叠。</li></ul></li><li><p><strong>未决PR</strong>：</p><ul><li>多个信使优化PR，正在持续优化中。</li><li>蓝办公室读取周期性丢弃功能和蓝存储PR，可能不会很快落地。</li></ul></li></ol><p><strong>二、性能瓶颈与优化</strong></p><ol><li><p><strong>信使线程</strong>：</p><ul><li>在低CPU使用场景下，信使线程在日志代码中锁定，消耗大量CPU资源。</li><li>考虑减少日志记录，或使用更高效的日志记录方式。</li><li>探讨使用自旋锁替换互斥锁的可能性。</li></ul></li><li><p><strong>对象生命周期与内存管理</strong>：</p><ul><li>在代码中创建和删除大量临时对象，导致性能开销。</li><li>寻找避免创建和删除对象的方法，优化对象生命周期。</li></ul></li></ol><p><strong>三、外部库优化</strong></p><ol><li><p><strong>外部库依赖</strong>：</p><ul><li>讨论了Ceph对外部库的依赖，特别是加密库。</li><li>考虑使用自定义版本的加密库，以获得更好的性能。</li><li>讨论了不同平台和硬件对性能的影响。</li></ul></li><li><p><strong>OpenSSL优化</strong>：</p><ul><li>探讨了使用OpenSSL异步接口和同步接口对性能的影响。</li><li>考虑使用OpenSSL的SSE4.2加速功能。</li></ul></li></ol><p><strong>四、其他讨论</strong></p><ol><li><strong>Keystone PKI令牌</strong>： <ul><li>讨论了Keystone PKI令牌的使用，以及可能的替代方案。</li><li>考虑使用OpenSSL的CMS支持。</li></ul></li></ol><p><strong>五、后续行动计划</strong></p><ol><li>继续跟踪和审查未决PR。</li><li>研究信使线程和对象生命周期优化方案。</li><li>探索外部库优化方案。</li><li>准备Nautilus发布。</li></ol><p><strong>六、会议总结</strong></p><p>本次会议讨论了Ceph项目的最新进展，包括PR更新、性能瓶颈优化和外部库优化。会议明确了后续行动计划，并确定了下一步工作重点。会议重点关注了信使线程的性能瓶颈、对象生命周期与内存管理优化，以及外部库的优化策略。</p><p>会议中提到的关键Ceph相关关键词包括：Ceph, distributed storage, CRUSH algorithm, high availability, scalability, object storage, block storage, file system storage, consistency, decentralization, performance, bluestore, bluefs, rocksdb, OSD, MON, MDS, PG, RADOS, librados, libcephfs, cephfs, rbd, radosgw, RGW, RESTful API, authentication, authorization, encryption, erasure coding, replication, snapshots, clones, thin provisioning, iSCSI, Fibre Channel, NFS, CIFS, POSIX, monitoring, dashboard, management, orchestration, automation, integration, containerization, Kubernetes, Docker, virtualization, cloud computing, AWS, Azure, Google Cloud, hybrid cloud, multi-cloud, storage cluster, node, disk, SSD, HDD, JBOD, SAN, NAS, network, topology, failure domain, recovery, resilience, load balancing, caching, compression, deduplication, tiering, performance tuning, benchmarking, testing, validation。</p>',18)])])}const _=e(n,[["render",r]]);export{d as __pageData,_ as default};
